func stepIndex(status string) int {
	for i, s := range model.ProgressSteps {
		if s.Value == status {
			return i
		}
	}
	return -1
}

func dotClass(i, k int) string {
	switch {
	case i < 0:
		return "dot"
	case k < i:
		return "dot done"
	case k == i:
		return "dot now"
	}
	return "dot"
}

